-- comments for challenge 2745
PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7601247, 1228119, 114285, '<td valign="top">Excellent. Spot on challenge!</td>', 'Excellent. Spot on challenge!', '2018-11-07 01:16:02.000000', NULL, 1),
(7601319, 1228297, 101256, '<td valign="top">Interesting combination of minimalism and impressionism. Great concept and execution. Marilyn Fenn is a minimalist artist and this channels her technique perfectly. Throw in a little Monet and the results are what this photographer produced.  Well done - most excellent.</td>', 'Interesting combination of minimalism and impressionism. Great concept and execution. Marilyn Fenn is a minimalist artist and this channels her technique perfectly. Throw in a little Monet and the results are what this photographer produced.  Well done - most excellent.', '2018-11-07 14:26:02.000000', NULL, 1),
(7601320, 1228277, 101256, '<td valign="top">I can tell already this is going to be a rare challenge - two great images back-to-back and I just got started. Love the post modern tone and approach to this image - simple, yet elegant - moody, yet purposeful - well done.</td>', 'I can tell already this is going to be a rare challenge - two great images back-to-back and I just got started. Love the post modern tone and approach to this image - simple, yet elegant - moody, yet purposeful - well done.', '2018-11-07 14:27:59.000000', NULL, 1),
(7601321, 1228304, 101256, '<td valign="top">Minimalist portraiture is almost (note almost)done in B&amp;W, but the overall tenor of this image approaches the best of the tonal qualities you get with B&amp;W using muted tones of brown and sepia. It reminds me very much of photographer Henrik Adamsen who does a lot of this type of imagery. I like this and is the third image that I can''t nitpick - its too perfect. Well done.</td>', 'Minimalist portraiture is almost (note almost)done in B&W, but the overall tenor of this image approaches the best of the tonal qualities you get with B&W using muted tones of brown and sepia. It reminds me very much of photographer Henrik Adamsen who does a lot of this type of imagery. I like this and is the third image that I can''t nitpick - its too perfect. Well done.', '2018-11-07 14:33:59.000000', NULL, 1),
(7601322, 1228187, 101256, '<td valign="top">A very competent image combining brown tones with white highlights. Plus, doggy pictures are always worth a second look - nice capture.</td>', 'A very competent image combining brown tones with white highlights. Plus, doggy pictures are always worth a second look - nice capture.', '2018-11-07 14:35:19.000000', NULL, 1),
(7601327, 1228127, 101256, '<td valign="top">A very Andrew B. Myers style in that the image invites you to keep looking for detail that isn''t there. Most excellent - well done.</td>', 'A very Andrew B. Myers style in that the image invites you to keep looking for detail that isn''t there. Most excellent - well done.', '2018-11-07 14:42:51.000000', NULL, 1),
(7601332, 1227890, 101256, '<td valign="top">An interesting landscape which could very well be classified as minimal, but frankly, minimalism isn''t just about lack of detail - in an odd fashion the minimalist to observe closely rather than just pass by. Great effort though.</td>', 'An interesting landscape which could very well be classified as minimal, but frankly, minimalism isn''t just about lack of detail - in an odd fashion the minimalist to observe closely rather than just pass by. Great effort though.', '2018-11-07 14:45:23.000000', NULL, 1),
(7601335, 1228314, 101256, '<td valign="top">I don''t see this as a minimalist cityscape. It is a very interesting image, but not minimal as I think of minimalist in scope or concept. But the other half of the challenge with minimal editing, this is really well done.</td>', 'I don''t see this as a minimalist cityscape. It is a very interesting image, but not minimal as I think of minimalist in scope or concept. But the other half of the challenge with minimal editing, this is really well done.', '2018-11-07 14:48:19.000000', NULL, 1),
(7601336, 1228233, 101256, '<td valign="top">Wonderful color combinations with simple, yet intriguing subjects - this is a true work of minimalist art - very evocative and interesting. Well done.</td>', 'Wonderful color combinations with simple, yet intriguing subjects - this is a true work of minimalist art - very evocative and interesting. Well done.', '2018-11-07 14:50:04.000000', NULL, 1),
(7601338, 1228109, 101256, '<td valign="top">This is a much more complex image that it first appears. It certainly fits the criteria of minimalist both in concept and execution, the sense of over whelming distance, time and space mirrors the minimalist genre perfectly. Well done.</td>', 'This is a much more complex image that it first appears. It certainly fits the criteria of minimalist both in concept and execution, the sense of over whelming distance, time and space mirrors the minimalist genre perfectly. Well done.', '2018-11-07 14:52:36.000000', NULL, 1),
(7601340, 1228265, 101256, '<td valign="top">Not to be pedantic but its really three fingers and a thumb. :)  Seriously, this is a perfect example of visualizing how a minimalist image should look and "feel". Such a simple concept, yet not so simple in execution. Well done.</td>', 'Not to be pedantic but its really three fingers and a thumb. :)  Seriously, this is a perfect example of visualizing how a minimalist image should look and "feel". Such a simple concept, yet not so simple in execution. Well done.', '2018-11-07 14:56:09.000000', NULL, 1),
(7601341, 1228213, 101256, '<td valign="top">This is very similar to a photographer I follow named Prakash Ghai - he has a knack for visualizing light and shadow keeping it simple and interesting - much like this image in fact.  A great image for this challenge - wonderful.</td>', 'This is very similar to a photographer I follow named Prakash Ghai - he has a knack for visualizing light and shadow keeping it simple and interesting - much like this image in fact.  A great image for this challenge - wonderful.', '2018-11-07 14:59:38.000000', NULL, 1),
(7601342, 1228260, 101256, '<td valign="top">Two colors, one subject - can''t get much more minimal. Great visualization and execution - wonderful.</td>', 'Two colors, one subject - can''t get much more minimal. Great visualization and execution - wonderful.', '2018-11-07 15:00:43.000000', NULL, 1),
(7601344, 1227853, 101256, '<td valign="top">This is an interesting combination of impressionism, minimalism and reality - I don''t know if the author intended it that way, but it turned out that way - a very interesting image and one that deserves some high marks for inventiveness.<br/>Sometimes we "see" something that doesn''t quite turn out the way we expect and I have a feeling this is one of those times.  Well done.</td>', 'This is an interesting combination of impressionism, minimalism and reality - I don''t know if the author intended it that way, but it turned out that way - a very interesting image and one that deserves some high marks for inventiveness.Sometimes we "see" something that doesn''t quite turn out the way we expect and I have a feeling this is one of those times.  Well done.', '2018-11-07 15:03:43.000000', NULL, 1),
(7601345, 1228303, 101256, '<td valign="top">Y''all are killing me in the challenge - I''m running out of words because most of these images are just too perfect in terms of minimalist concepts. This is just simple brilliant - light, shadow, muted color, detailed background - very well conceived and executed.  Well done.</td>', 'Y''all are killing me in the challenge - I''m running out of words because most of these images are just too perfect in terms of minimalist concepts. This is just simple brilliant - light, shadow, muted color, detailed background - very well conceived and executed.  Well done.', '2018-11-07 15:06:03.000000', NULL, 1),
(7601347, 1228258, 101256, '<td valign="top">While minimalist in concept, there are some technical issues that detract from the overall impact of the image. The tilted horizon and the positioning of the rock islands are distracting - a little more thought and patience would have made this a much better image.</td>', 'While minimalist in concept, there are some technical issues that detract from the overall impact of the image. The tilted horizon and the positioning of the rock islands are distracting - a little more thought and patience would have made this a much better image.', '2018-11-07 15:08:04.000000', NULL, 1),
(7601348, 1228234, 101256, '<td valign="top">This is a great image and in another context, would probably place pretty high, but as far as "minimalist", I can''t honestly say it fits the criteria. On the other hand, sans editing, or minimal editing, it is a great image and gets a high mark just for that.</td>', 'This is a great image and in another context, would probably place pretty high, but as far as "minimalist", I can''t honestly say it fits the criteria. On the other hand, sans editing, or minimal editing, it is a great image and gets a high mark just for that.', '2018-11-07 15:09:49.000000', NULL, 1),
(7601349, 1228221, 101256, '<td valign="top">Wow - another great concept and terrific execution. Minimalist perfection - excellent - well done.</td>', 'Wow - another great concept and terrific execution. Minimalist perfection - excellent - well done.', '2018-11-07 15:11:14.000000', NULL, 1),
(7601350, 1228220, 101256, '<td valign="top">This image is pure genius - absolutely perfect in every sense of the word - I can''t say anything more - this deserves to win hands down.</td>', 'This image is pure genius - absolutely perfect in every sense of the word - I can''t say anything more - this deserves to win hands down.', '2018-11-07 15:12:53.000000', NULL, 1),
(7601351, 1228132, 101256, '<td valign="top">While the construction of this image is minimalist, it sort of fails in execution on second viewing. A little more thought and some judicious cropping would improve this tremendously.</td>', 'While the construction of this image is minimalist, it sort of fails in execution on second viewing. A little more thought and some judicious cropping would improve this tremendously.', '2018-11-07 15:14:53.000000', NULL, 1),
(7601352, 1228266, 101256, '<td valign="top">A good effort, but it lacks the interest that others in this challenge - on third viewing, I really can''t give it super high marks, although it does meet the criteria. However, it is a worthy effort and that counts for a lot.</td>', 'A good effort, but it lacks the interest that others in this challenge - on third viewing, I really can''t give it super high marks, although it does meet the criteria. However, it is a worthy effort and that counts for a lot.', '2018-11-07 15:17:07.000000', NULL, 1),
(7601353, 1228284, 101256, '<td valign="top">This has the look of a pencil drawing - great execution and compelling concept.<br/>Well done.</td>', 'This has the look of a pencil drawing - great execution and compelling concept.Well done.', '2018-11-07 15:18:50.000000', NULL, 1),
(7601354, 1228218, 101256, '<td valign="top">This will probably annoy the author, but I think this would have worked much better in black and white or grey scale.Having said that, this has a lot working for it - the vagueness of the background, sharp/clear subject - it has all the prerequisites of a minimalist image (and in fact IS a minimalist image), but in my opinion, it just doesn''t work with these colors. Still, a worthy entry.</td>', 'This will probably annoy the author, but I think this would have worked much better in black and white or grey scale.Having said that, this has a lot working for it - the vagueness of the background, sharp/clear subject - it has all the prerequisites of a minimalist image (and in fact IS a minimalist image), but in my opinion, it just doesn''t work with these colors. Still, a worthy entry.', '2018-11-07 15:22:22.000000', NULL, 1),
(7601355, 1228013, 101256, '<td valign="top">A little better shooting placement and some patience would have helped this a lot. The darker foreground is disturbed by the TV antenna and the sun bloom sort of ruins the "dark and gloomy" effect I believe the author was after. It has elements of minimalism, but fails to be complete. Still, effort counts.</td>', 'A little better shooting placement and some patience would have helped this a lot. The darker foreground is disturbed by the TV antenna and the sun bloom sort of ruins the "dark and gloomy" effect I believe the author was after. It has elements of minimalism, but fails to be complete. Still, effort counts.', '2018-11-07 15:25:14.000000', NULL, 1),
(7601356, 1228293, 101256, '<td valign="top">Both simple and complex - elegant in conception and execution. Its a little too busy to be "minimalist" in my opinion, but I can see what the author is looking at here and agree that it certainly fits the criteria. Well done.</td>', 'Both simple and complex - elegant in conception and execution. Its a little too busy to be "minimalist" in my opinion, but I can see what the author is looking at here and agree that it certainly fits the criteria. Well done.', '2018-11-07 15:27:39.000000', NULL, 1),
(7601357, 1228110, 101256, '<td valign="top">Another great image where the nexus of impressionist and realism come together in a perfect blend of minimalist art. Well done.</td>', 'Another great image where the nexus of impressionist and realism come together in a perfect blend of minimalist art. Well done.', '2018-11-07 15:28:36.000000', NULL, 1),
(7601359, 1227948, 101256, '<td valign="top">I have looked at this four times today and can''t decide exactly where it fits in the pantheon of "minimalist" imagery - or if it does for that matter. Rather than debate with myself which is counter productive, I''ll just grade it as a great image, well executed and let others decide about it making or breaking the challenge. Great image - I really like it.</td>', 'I have looked at this four times today and can''t decide exactly where it fits in the pantheon of "minimalist" imagery - or if it does for that matter. Rather than debate with myself which is counter productive, I''ll just grade it as a great image, well executed and let others decide about it making or breaking the challenge. Great image - I really like it.', '2018-11-07 15:31:09.000000', NULL, 1),
(7601360, 1228119, 101256, '<td valign="top">Wonderful image - the sense of purpose and a feeling of a never ending stair case - really well done.</td>', 'Wonderful image - the sense of purpose and a feeling of a never ending stair case - really well done.', '2018-11-07 15:33:41.000000', NULL, 1),
(7601361, 1228222, 101256, '<td valign="top">I think this image would have worked better without the single climber - in my opinion, it just throws the balance of the image off and detracts from the overall impact of the staircase. Still, it works on a lot of other levels - wel done.</td>', 'I think this image would have worked better without the single climber - in my opinion, it just throws the balance of the image off and detracts from the overall impact of the staircase. Still, it works on a lot of other levels - wel done.', '2018-11-07 15:35:24.000000', NULL, 1),
(7601362, 1228211, 101256, '<td valign="top">I like the idea - I like the shadow and the green junctions - I really just am not that interested in this as a image - there''s something lacking to give it some "punch" if you will. Perhaps if you had some a more macro look at the water drops, it would have made it more interesting.</td>', 'I like the idea - I like the shadow and the green junctions - I really just am not that interested in this as a image - there''s something lacking to give it some "punch" if you will. Perhaps if you had some a more macro look at the water drops, it would have made it more interesting.', '2018-11-07 15:37:58.000000', NULL, 1),
(7601473, 1228234, 97225, '<td valign="top">No doubt you adhered to the minimal rules and this is a lovely shot but the image is in no way minimalist.</td>', 'No doubt you adhered to the minimal rules and this is a lovely shot but the image is in no way minimalist.', '2018-11-08 01:08:06.000000', NULL, 1),
(7601474, 1228314, 97225, '<td valign="top">Minimal editing okay, but definitely not a Minimalist image.</td>', 'Minimal editing okay, but definitely not a Minimalist image.', '2018-11-08 01:09:14.000000', NULL, 1),
(7601475, 1227793, 97225, '<td valign="top">Beautiful shot but not Minimalism.</td>', 'Beautiful shot but not Minimalism.', '2018-11-08 01:10:09.000000', NULL, 1),
(7601476, 1228187, 97225, '<td valign="top">Lovely shot, but not Minimalism.</td>', 'Lovely shot, but not Minimalism.', '2018-11-08 01:10:47.000000', NULL, 1),
(7601477, 1228223, 97225, '<td valign="top">Interesting capture but the challenge calls for a minimalist image (not just minimal editing).</td>', 'Interesting capture but the challenge calls for a minimalist image (not just minimal editing).', '2018-11-08 01:12:02.000000', NULL, 1),
(7601478, 1228255, 97225, '<td valign="top">Moderately simple but too complicated for Minimalism.</td>', 'Moderately simple but too complicated for Minimalism.', '2018-11-08 01:13:12.000000', NULL, 1),
(7601479, 1227948, 97225, '<td valign="top">I don''t see this as Minimalism (even though you probably followed minimal editing rules).</td>', 'I don''t see this as Minimalism (even though you probably followed minimal editing rules).', '2018-11-08 01:15:02.000000', NULL, 1),
(7601517, 1228309, 101256, '<td valign="top">Great concept - this might have been a better construct if you had just used the clouds - the bird lacks enough detail to have any sort of meaningful impression.</td>', 'Great concept - this might have been a better construct if you had just used the clouds - the bird lacks enough detail to have any sort of meaningful impression.', '2018-11-08 10:00:58.000000', NULL, 1),
(7601518, 1227793, 101256, '<td valign="top">Absolutely gorgeous image - almost too perfect if that''s possible. Well done.</td>', 'Absolutely gorgeous image - almost too perfect if that''s possible. Well done.', '2018-11-08 10:02:12.000000', NULL, 1),
(7601519, 1228306, 101256, '<td valign="top">Another excellent image in the minimalist genre - the combination of simple structure,angles and color is perfect. Well done.</td>', 'Another excellent image in the minimalist genre - the combination of simple structure,angles and color is perfect. Well done.', '2018-11-08 10:03:51.000000', NULL, 1),
(7601520, 1228253, 101256, '<td valign="top">Not sure what to do here - in my opinion, I don''t believe it meets the challenge or perhaps it does, but in a certain sense of the term minimal.</td>', 'Not sure what to do here - in my opinion, I don''t believe it meets the challenge or perhaps it does, but in a certain sense of the term minimal.', '2018-11-08 10:05:20.000000', NULL, 1),
(7601521, 1227745, 101256, '<td valign="top">Certainly meets the challenge criteria, but I can''t help thinking that a little cropping off the top would have been a better choice displaying three steps rather than the four. Still, it certainly is minimalist.</td>', 'Certainly meets the challenge criteria, but I can''t help thinking that a little cropping off the top would have been a better choice displaying three steps rather than the four. Still, it certainly is minimalist.', '2018-11-08 10:07:46.000000', NULL, 1),
(7601522, 1228028, 101256, '<td valign="top">I''m not really sure - minimalism should have some context - or to put it another way, the viewer should be able to place context on the image. I''m not sure about this - looked at it a couple of times, but I still can''t "see" the intent.</td>', 'I''m not really sure - minimalism should have some context - or to put it another way, the viewer should be able to place context on the image. I''m not sure about this - looked at it a couple of times, but I still can''t "see" the intent.', '2018-11-08 10:10:22.000000', NULL, 1),
(7601524, 1228283, 101256, '<td valign="top">Very interesting - I wonder how many saw the moon in the upper left? :) Very nice and certainly meets the criteria. Nice.</td>', 'Very interesting - I wonder how many saw the moon in the upper left? :) Very nice and certainly meets the criteria. Nice.', '2018-11-08 10:12:24.000000', NULL, 1),
(7601525, 1228223, 101256, '<td valign="top">Nice image - interesting subject, but I''m not sure it meets challenge criteria. But as a nature photo, it''s very good. I like it.</td>', 'Nice image - interesting subject, but I''m not sure it meets challenge criteria. But as a nature photo, it''s very good. I like it.', '2018-11-08 10:13:36.000000', NULL, 1),
(7601526, 1228298, 101256, '<td valign="top">Minimalist impressionism....now that''s different. I like it - the blend of light and color, plus the additional look at trees framing the whole image is really good.  Well done.</td>', 'Minimalist impressionism....now that''s different. I like it - the blend of light and color, plus the additional look at trees framing the whole image is really good.  Well done.', '2018-11-08 10:14:58.000000', NULL, 1),
(7601528, 1227719, 101256, '<td valign="top">Another wonderful image meeting the challenge criteria - well done.</td>', 'Another wonderful image meeting the challenge criteria - well done.', '2018-11-08 10:17:31.000000', NULL, 1),
(7601529, 1228292, 101256, '<td valign="top">Gorgeous and certainly meets the challenge criteria head on - beautiful and very evocative...this image has the "wow" factor often missing in this type of photography.  Well Done.</td>', 'Gorgeous and certainly meets the challenge criteria head on - beautiful and very evocative...this image has the "wow" factor often missing in this type of photography.  Well Done.', '2018-11-08 10:18:21.000000', NULL, 1),
(7601532, 1227953, 101256, '<td valign="top">I like the idea here, but I think it misses the intent of the challenge criteria. Reframing the image to just the plant, window and light would have been perfect to my way of thinking.</td>', 'I like the idea here, but I think it misses the intent of the challenge criteria. Reframing the image to just the plant, window and light would have been perfect to my way of thinking.', '2018-11-08 10:20:04.000000', NULL, 1),
(7601534, 1228235, 101256, '<td valign="top">What an interesting image - has a lot of meaning and purpose - very different interpretation of minimalism - well done.</td>', 'What an interesting image - has a lot of meaning and purpose - very different interpretation of minimalism - well done.', '2018-11-08 10:21:18.000000', NULL, 1),
(7601538, 1228312, 101256, '<td valign="top">There is a photographer named John Estes who does imagery very similar to this - he takes long angled shots with simple subject matter - in this case, its a similar technique in a minimalist approach. Very well conceived and executed.</td>', 'There is a photographer named John Estes who does imagery very similar to this - he takes long angled shots with simple subject matter - in this case, its a similar technique in a minimalist approach. Very well conceived and executed.', '2018-11-08 10:24:25.000000', NULL, 1),
(7601540, 1227844, 101256, '<td valign="top">A different look at the challenge criteria - simple and elegant - a very interesting image.</td>', 'A different look at the challenge criteria - simple and elegant - a very interesting image.', '2018-11-08 10:25:42.000000', NULL, 1),
(7601541, 1227870, 101256, '<td valign="top">There is a still life photographer named Susan Cummings who produces images very similar to this - simple, elegant and purposeful. An excellent example of the genre.</td>', 'There is a still life photographer named Susan Cummings who produces images very similar to this - simple, elegant and purposeful. An excellent example of the genre.', '2018-11-08 10:28:56.000000', NULL, 1),
(7601602, 1228127, 8891, '<td valign="top"><strike></strike>[img][/img]</td>', '[img][/img]', '2018-11-08 15:48:14.000000', NULL, 1),
(7601619, 1227844, 180799, '<td valign="top">Love this photo!  The wide expanse of the field narrows the focus to the movement and energy of the horse.  I can almost hear the hoofbeats.</td>', 'Love this photo!  The wide expanse of the field narrows the focus to the movement and energy of the horse.  I can almost hear the hoofbeats.', '2018-11-08 18:11:36.000000', NULL, 1),
(7601723, 1228305, 101256, '<td valign="top">Interesting interpretation of the challenge criteria - it would have presented better, in my opinion, with a little more foreground....</td>', 'Interesting interpretation of the challenge criteria - it would have presented better, in my opinion, with a little more foreground....', '2018-11-09 09:33:20.000000', NULL, 1),
(7601724, 1228276, 101256, '<td valign="top">This image became better and better every time I viewed it. The cool color combined with the hot spot blooms make it an compelling image. Well done.</td>', 'This image became better and better every time I viewed it. The cool color combined with the hot spot blooms make it an compelling image. Well done.', '2018-11-09 09:35:18.000000', NULL, 1),
(7601725, 1228106, 101256, '<td valign="top">A rather puzzling image in that it has elements of both realism and minimalism...worthy entry that meets the challenge criteria very nicely.</td>', 'A rather puzzling image in that it has elements of both realism and minimalism...worthy entry that meets the challenge criteria very nicely.', '2018-11-09 09:38:17.000000', NULL, 1),
(7601726, 1227726, 101256, '<td valign="top">Really like this one - elegantly simple, yet complex in its ability to create a "wow" factor response. Very well conceived and executed.</td>', 'Really like this one - elegantly simple, yet complex in its ability to create a "wow" factor response. Very well conceived and executed.', '2018-11-09 09:40:15.000000', NULL, 1),
(7601727, 1228224, 101256, '<td valign="top">While I wouldn''t consider this "minimalist", I really like the burn marks around the flame warning.....amusing....</td>', 'While I wouldn''t consider this "minimalist", I really like the burn marks around the flame warning.....amusing....', '2018-11-09 09:41:44.000000', NULL, 1),
(7601728, 1227732, 101256, '<td valign="top">Another excellent still life with muted colors and very interesting lighting. I really enjoy the creativity that go into creating and capturing images like this.  Well done.</td>', 'Another excellent still life with muted colors and very interesting lighting. I really enjoy the creativity that go into creating and capturing images like this.  Well done.', '2018-11-09 09:43:06.000000', NULL, 1),
(7601729, 1228295, 101256, '<td valign="top">I''m not sure what the author''s thought process was here, but I''m leaning towards the leaf? I don''t know - but, it certainly meets the challenge criteria.</td>', 'I''m not sure what the author''s thought process was here, but I''m leaning towards the leaf? I don''t know - but, it certainly meets the challenge criteria.', '2018-11-09 09:44:32.000000', NULL, 1),
(7601730, 1227728, 101256, '<td valign="top">A refreshing look at the concept of minimalism. There really isn''t much to say about it - just look and wonder. Well done.</td>', 'A refreshing look at the concept of minimalism. There really isn''t much to say about it - just look and wonder. Well done.', '2018-11-09 09:46:42.000000', NULL, 1),
(7601731, 1228310, 101256, '<td valign="top">Took me a minute to get it, but I did - very clever - I just finished reading a novel that had the protagonists look for subtle clues for direction and this reminded me of that.</td>', 'Took me a minute to get it, but I did - very clever - I just finished reading a novel that had the protagonists look for subtle clues for direction and this reminded me of that.', '2018-11-09 09:49:03.000000', NULL, 1),
(7601733, 1228078, 101256, '<td valign="top">I really enjoy images that don''t take a lot of thought and play on whimsy and humor - I really like this - well done.</td>', 'I really enjoy images that don''t take a lot of thought and play on whimsy and humor - I really like this - well done.', '2018-11-09 09:50:29.000000', NULL, 1),
(7601734, 1228272, 101256, '<td valign="top">A very nice nature image - I like the combination of color and light. I can''t decide if it is a little out of focus or not - in any case, a very pleasant image to look at.</td>', 'A very nice nature image - I like the combination of color and light. I can''t decide if it is a little out of focus or not - in any case, a very pleasant image to look at.', '2018-11-09 09:51:57.000000', NULL, 1),
(7601735, 1228240, 101256, '<td valign="top">I believe I can see what the author was looking for here, but it doesn''t really have the impact it needs. The background sort of disturbs the intent by drawing the eye first rather than the subject.</td>', 'I believe I can see what the author was looking for here, but it doesn''t really have the impact it needs. The background sort of disturbs the intent by drawing the eye first rather than the subject.', '2018-11-09 09:54:18.000000', NULL, 1),
(7601736, 1228279, 101256, '<td valign="top">Very interesting image. Not without merit it certainly meets the criteria.</td>', 'Very interesting image. Not without merit it certainly meets the criteria.', '2018-11-09 09:56:15.000000', NULL, 1),
(7601737, 1228136, 101256, '<td valign="top">A lot of peas in this challenge. :) Certainly is minimal in concept and construction. Interesting color play on the pea and I like the mixture of background and shadow. Very good entry.</td>', 'A lot of peas in this challenge. :) Certainly is minimal in concept and construction. Interesting color play on the pea and I like the mixture of background and shadow. Very good entry.', '2018-11-09 09:57:48.000000', NULL, 1),
(7601738, 1228255, 101256, '<td valign="top">I really don''t know what to day about this - I found the top board much more interesting (with the knots) than the rest of the image. I felt the image is a little too busy to be truly minimalist, but I can see the author''s intent and we all don''t look at the same thing in the same way.</td>', 'I really don''t know what to day about this - I found the top board much more interesting (with the knots) than the rest of the image. I felt the image is a little too busy to be truly minimalist, but I can see the author''s intent and we all don''t look at the same thing in the same way.', '2018-11-09 10:00:25.000000', NULL, 1),
(7601848, 1227793, 81362, '<td valign="top">Very nice image for minimal editing rules. The still water with excellent reflections is a kind of minimalism, but the image strays somewhat away from the topic because of the complexity of lines and objects.</td>', 'Very nice image for minimal editing rules. The still water with excellent reflections is a kind of minimalism, but the image strays somewhat away from the topic because of the complexity of lines and objects.', '2018-11-09 20:14:31.000000', NULL, 1),
